#!/bin/bash
# run the serial engine on both nodes: run2.sh [extra args...]
set -e
cd /home/urtho/dev/_experiments/ai/tensorfold
rsync -a --exclude .venv --exclude .git --exclude notes/ref --exclude out --exclude __pycache__ --exclude .claude ./ aiai:tensorfold/
rsync -a --exclude .venv --exclude .git --exclude notes/ref --exclude out --exclude __pycache__ --exclude .claude ./ aiai2:tensorfold/
# leftover ranks of a killed run hold memory and the rendezvous port
for h in aiai aiai2; do timeout 30 ssh $h "docker exec tf-dev pkill -f 'tools/dsv41_' ; true" >/dev/null 2>&1; done
sleep 3
# TF_DUAL=1: both PCIe halves of the 200G port (second half: 10.43.0.1/.2 in NM profile cx7-companion-mtu)
if [ "${TF_DUAL:-0}" = 1 ]; then H0="=roceP2p1s0f1,rocep1s0f1"; H1="=roceP2p1s0f1,rocep1s0f1"; else H0=roceP2p1s0f1; H1=roceP2p1s0f1; fi
NSYS=""; [ -n "${TF_NSYS:-}" ] && NSYS="nsys profile -o /tf/nsys_step -f true --capture-range=cudaProfilerApi --cuda-graph-trace=node --trace=cuda"
# no fixed GID index: the index of a port's RoCE v2 IPv4 GID moves (3 or 4, per device) when an address is re-added
# under a live connection; NCCL picks it per device by version and family, the RoCE all-gather by type and address.
# NCCL_IB_GID_INDEX=N in the caller's environment still pins it.
GIDENV="-e NCCL_IB_ROCE_VERSION_NUM=2 -e NCCL_IB_ADDR_FAMILY=AF_INET -e NCCL_IB_ADDR_RANGE=${NCCL_IB_ADDR_RANGE:-10.42.0.0/15}"
[ -n "${NCCL_IB_GID_INDEX:-}" ] && GIDENV="$GIDENV -e NCCL_IB_GID_INDEX=$NCCL_IB_GID_INDEX"
M=/models/dsv41/DeepSeek-V4.1-Flash-EXL3-2.9bpw; G=/models/dsv41/DeepSeek-V4.1-Flash-engram
# prepared per-rank weight folders (make prepare's PREPARED_DIR, mounted read-only at /prepared in tf-dev): a ~24 s read
# instead of the ~82 s build while the weights code matches the folder's key (fastboot.py); TF_DSV41_PREPARED= (set,
# empty) builds from the checkpoint. tools/dsv41_tfdev_recreate.py adds the mount.
if [ -z "${TF_DSV41_PREPARED+x}" ]; then
  if timeout 20 ssh aiai "docker exec tf-dev test -d /prepared" && timeout 20 ssh aiai2 "docker exec tf-dev test -d /prepared"; then
    TF_DSV41_PREPARED=/prepared
  else
    echo "tf-dev has no /prepared on both nodes: weights build from the checkpoint (tools/dsv41_tfdev_recreate.py)"
    TF_DSV41_PREPARED=
  fi
fi
# expandable segments, as the compose server runs: without them the prepared-weights load leaves ~4.7 GiB reserved but
# unusable (a 64K teacher-forced document then OOMs under the allocator cap). The caller's PYTORCH_CUDA_ALLOC_CONF
# wins; set and empty: torch's default allocator.
PYTORCH_CUDA_ALLOC_CONF=${PYTORCH_CUDA_ALLOC_CONF-expandable_segments:True}
# the OOM guard (notes/dsv41/DEV.md): a tag naming this run's processes; a watcher on each node that kills only them
# below TF_MEMWATCH_GIB (3; 0: no watcher) of MemAvailable and ends with the run; the in-process allocator cap
# (tools/dsv41_memguard.py: TF_MEM_CAP_GIB, TF_MEM_RESERVE_GIB, TF_MEM_SLACK_GIB, TF_MEM_MIN_START_GIB)
TAG=run$(date +%s)-$$
MEMARGS="--run-tag $TAG"
[ -z "${TF_MEM_CAP_GIB:-}" ] || MEMARGS="$MEMARGS --mem-cap-gib $TF_MEM_CAP_GIB"
[ -z "${TF_MEM_RESERVE_GIB:-}" ] || MEMARGS="$MEMARGS --mem-reserve-gib $TF_MEM_RESERVE_GIB"
[ -z "${TF_MEM_SLACK_GIB:-}" ] || MEMARGS="$MEMARGS --mem-slack-gib $TF_MEM_SLACK_GIB"
[ -z "${TF_MEM_MIN_START_GIB:-}" ] || MEMARGS="$MEMARGS --mem-min-start-gib $TF_MEM_MIN_START_GIB"
# shellcheck disable=SC2086
set -- $MEMARGS "$@"                    # first: flags given to this script still win
MW_GIB=${TF_MEMWATCH_GIB:-3}
GRACE=15
finish() {
  # the watchers off; a rank of this run still there after GRACE s (the other failed or was killed) killed
  for h in aiai aiai2; do
    timeout 60 ssh $h "docker exec tf-dev bash /tf/tools/dsv41_memwatch.sh --stop $TAG $GRACE" 2>/dev/null | sed "s/^/[$h] /"
  done
}
trap finish EXIT
trap 'GRACE=0; exit 130' INT TERM
if [ "$MW_GIB" != 0 ]; then
  for h in aiai aiai2; do timeout 30 ssh $h "docker exec -d tf-dev bash /tf/tools/dsv41_memwatch.sh $TAG $MW_GIB"; done
fi
timeout 30 ssh aiai2 "docker exec -d -e NCCL_SOCKET_IFNAME=enP2p1s0f1np1 -e NCCL_IB_HCA=$H1 $GIDENV -e NCCL_DEBUG=ERROR -e NCCL_PROTO=${NCCL_PROTO:-} -e TF_PAR=${TF_PAR:-1} -e TF_CARVEOUT=${TF_CARVEOUT:-} -e TF_DSV41_KV_FP8=${TF_DSV41_KV_FP8:-} -e TF_DSV41_KV=${TF_DSV41_KV:-} -e TF_DSV41_IQ_FP4=${TF_DSV41_IQ_FP4:-} -e TF_DSV41_SWA_FP8=${TF_DSV41_SWA_FP8:-} -e TF_DSV41_COMP_BF16=${TF_DSV41_COMP_BF16:-} -e PYTORCH_CUDA_ALLOC_CONF=${PYTORCH_CUDA_ALLOC_CONF:-} -e TF_ROUTE_STATS=${TF_ROUTE_STATS:-} -e TF_ZB=${TF_ZB:-121,101} -e TF_ROUND_PROF=${TF_ROUND_PROF:-} -e TF_STEP_THREADS=${TF_STEP_THREADS:-16} -e TF_SKIP_READS=${TF_SKIP_READS:-} -e TF_SPLIT_READS=${TF_SPLIT_READS:-} -e TF_SKIP_SHARED=${TF_SKIP_SHARED:-} -e TF_FOLD_SHARED=${TF_FOLD_SHARED:-} -e TF_ROUTER_SLICES=${TF_ROUTER_SLICES:-} -e TF_L2_PREFETCH=${TF_L2_PREFETCH:-} -e TF_L2_SITES=${TF_L2_SITES:-} -e TF_L2_PACE_GBPS=${TF_L2_PACE_GBPS:-} -e TF_L2_PACE_CTAS=${TF_L2_PACE_CTAS:-} -e TF_L2_PACE_DELAY_US=${TF_L2_PACE_DELAY_US:-} -e TF_L2_PACE_SITES=${TF_L2_PACE_SITES:-} -e TF_L2_JOIN=${TF_L2_JOIN:-} -e TF_DSV41_DRAFT_RESET=${TF_DSV41_DRAFT_RESET:-} -e TF_DSV41_DRAFT_PRIOR=${TF_DSV41_DRAFT_PRIOR:-} -e TF_DSV41_DRAFT_RELAX=${TF_DSV41_DRAFT_RELAX:-} -e TF_DSV41_DRAFT_GRAMMAR=${TF_DSV41_DRAFT_GRAMMAR:-} -e TF_DSV41_COSTS=${TF_DSV41_COSTS:-} -e TF_DSV41_COST_CURVE=${TF_DSV41_COST_CURVE:-} -e TF_DSV41_CALIB_REPS=${TF_DSV41_CALIB_REPS:-} -e TF_DSV41_DRAFT_BORROW=${TF_DSV41_DRAFT_BORROW:-} -e TF_DSV41_L2_DISCARD_ROWS=${TF_DSV41_L2_DISCARD_ROWS:-} -e TF_MULTI_PROF=${TF_MULTI_PROF:-} -e TF_FUSE_HC_DECODE=${TF_FUSE_HC_DECODE:-} -e TF_SUBPROF=${TF_SUBPROF:-} -e TF_GROUPED_WO_A=${TF_GROUPED_WO_A:-} -e TF_MQA_CHUNK=${TF_MQA_CHUNK:-} -e TF_EXL3_ROT_FUSE=${TF_EXL3_ROT_FUSE:-} -e TF_PF_WOA=${TF_PF_WOA:-} -e TF_PF_PROGRAMS=${TF_PF_PROGRAMS:-} -e TF_COPY_DRAFTS=${TF_COPY_DRAFTS:-} -e TF_COPY_MAX=${TF_COPY_MAX:-} -e TF_COMM=${TF_COMM:-} -e TF_RDMA_MAX_KB=${TF_RDMA_MAX_KB:-} -e TF_RDMA_HOST=${TF_RDMA_HOST:-} -e TF_DSV41_MARKOV=${TF_DSV41_MARKOV:-} -e TF_DSV41_MARKOV_CACHE=${TF_DSV41_MARKOV_CACHE:-} -e TF_ONE_GRAPH=${TF_ONE_GRAPH:-} -e TF_DSV41_SHARED_POOL=${TF_DSV41_SHARED_POOL:-} -e TF_DSV41_POOL_TOKENS=${TF_DSV41_POOL_TOKENS:-} -e TF_DSV41_KEPT_ENTRIES=${TF_DSV41_KEPT_ENTRIES:-} -e TF_DSV41_KEEP_MIN=${TF_DSV41_KEEP_MIN:-} -e TF_DSV41_POOL_KEEP=${TF_DSV41_POOL_KEEP:-} -e TF_DSV41_GROW_AHEAD=${TF_DSV41_GROW_AHEAD:-} -e TF_CHUNK_PREFILL=${TF_CHUNK_PREFILL:-} -e TF_DSV41_FAST_TOPK=${TF_DSV41_FAST_TOPK:-} -e TF_DSV41_PREPARED=${TF_DSV41_PREPARED:-} -e TF_EXPERT_LOADS=${TF_EXPERT_LOADS:-} -e TF_EXPERT_LOADS_CFG=${TF_EXPERT_LOADS_CFG:-} -e TF_TAIL_TEST=${TF_TAIL_TEST:-} -e TF_DSV41_BOUNDED_TAIL=${TF_DSV41_BOUNDED_TAIL:-} -e NUMPY_MADVISE_HUGEPAGE=0 -e TF_DSV41_WIDTHS=${TF_DSV41_WIDTHS:-} -e TF_DSV41_SHARED_GRAPHS=${TF_DSV41_SHARED_GRAPHS:-} -e TF_NSYS=${TF_NSYS:-} -e TF_DECODE_PROF=${TF_DECODE_PROF:-} -e TF_DSV41_CUDA_MQA=${TF_DSV41_CUDA_MQA:-} -e TF_DSV41_SHARED_IK=${TF_DSV41_SHARED_IK:-} -e TF_DSV41_MQA_GROUP=${TF_DSV41_MQA_GROUP:-} -e TF_DSV41_MQA_FEW=${TF_DSV41_MQA_FEW:-} -e TF_DECODE_ROWS=${TF_DECODE_ROWS:-} -e TF_PROF_AT=${TF_PROF_AT:-} -e TF_STUDY_TIE=${TF_STUDY_TIE:-} -e TF_DSV41_SELECT_ONCE=${TF_DSV41_SELECT_ONCE:-} -e TF_DSV41_SEG_ROWS=${TF_DSV41_SEG_ROWS:-} -e TF_DSV41_FULL_DEQ=${TF_DSV41_FULL_DEQ:-} -e TF_DSV41_FULL_DEQ_MIB=${TF_DSV41_FULL_DEQ_MIB:-} -e TF_DSV41_IDX_BASE=${TF_DSV41_IDX_BASE:-} -e TF_DSV41_HC_SPLIT=${TF_DSV41_HC_SPLIT:-} -e TF_DSV41_HC_SIDE=${TF_DSV41_HC_SIDE:-} -e TF_DSV41_HC_SIDE_PART=${TF_DSV41_HC_SIDE_PART:-} -e TF_X3LD_ORDER=${TF_X3LD_ORDER:-} -e TF_EXPERT_GROUP=${TF_EXPERT_GROUP:-} -e TF_X3LD_PDL=${TF_X3LD_PDL:-} -e TF_DSV41_CAND_BOUND=${TF_DSV41_CAND_BOUND:-} -e TF_DSV41_ROUTE_WARPS=${TF_DSV41_ROUTE_WARPS:-} -e TF_ROUTER_BE=${TF_ROUTER_BE:-} -e TF_DSV41_TOPK_DIGITS=${TF_DSV41_TOPK_DIGITS:-} -e TF_DSV41_IDX_FORK=${TF_DSV41_IDX_FORK:-} -e TF_DSV41_PREFILL_PROF=${TF_DSV41_PREFILL_PROF:-} -e TF_DSV41_PREFILL_AHEAD=${TF_DSV41_PREFILL_AHEAD:-} -e TF_L2_ATTN_WQB_MB=${TF_L2_ATTN_WQB_MB:-} -e TF_DSV41_PROMPT_CHUNK=${TF_DSV41_PROMPT_CHUNK:-} -e TF_X3LD_PROBE=${TF_X3LD_PROBE:-} -e TF_DSV41_L2_DISCARD=${TF_DSV41_L2_DISCARD:-} -e TF_DSV41_RES_FOLD=${TF_DSV41_RES_FOLD:-} -e TF_COPY_MATCH=${TF_COPY_MATCH:-} -e TF_MULTI_COPY=${TF_MULTI_COPY:-} -e TF_MULTI_COPY_MIN=${TF_MULTI_COPY_MIN:-} -e TF_MULTI_CHECK=${TF_MULTI_CHECK:-} -e TF_RDMA_TRACE=${TF_RDMA_TRACE:-} -e TF_RDMA_COPY=${TF_RDMA_COPY:-} -e TF_RDMA_TRACE_OUT=${TF_RDMA_TRACE_OUT:-} -e TF_DSV41_SEND=${TF_DSV41_SEND:-} -e TF_DSV41_ROT_FUSE=${TF_DSV41_ROT_FUSE:-} -e TF_DSV41_WARM_SERVING=${TF_DSV41_WARM_SERVING:-} -e TF_DSV41_WARM_RARE=${TF_DSV41_WARM_RARE:-} -e TF_DSV41_WARM_TRACE=${TF_DSV41_WARM_TRACE:-} -e TF_DSV41_PDL=${TF_DSV41_PDL:-} -e TF_DSV41_DRAFT_GROUP=${TF_DSV41_DRAFT_GROUP:-} -e TF_EXL3_LANES=${TF_EXL3_LANES:-} -e TF_EXL3_LANES_HEAD=${TF_EXL3_LANES_HEAD:-} -e NCCL_ALGO=${NCCL_ALGO:-} tf-dev bash -c 'cd /tf && python tools/dsv41_serial_run.py $M $G --rank 1 --master 10.42.0.1 $* > /tf/serial-r1.log 2>&1'"
timeout 3000 ssh aiai "docker exec -e NCCL_SOCKET_IFNAME=enP2p1s0f1np1 -e NCCL_IB_HCA=$H0 $GIDENV -e NCCL_DEBUG=ERROR -e NCCL_PROTO=${NCCL_PROTO:-} -e TF_PAR=${TF_PAR:-1} -e TF_CARVEOUT=${TF_CARVEOUT:-} -e TF_DSV41_KV_FP8=${TF_DSV41_KV_FP8:-} -e TF_DSV41_KV=${TF_DSV41_KV:-} -e TF_DSV41_IQ_FP4=${TF_DSV41_IQ_FP4:-} -e TF_DSV41_SWA_FP8=${TF_DSV41_SWA_FP8:-} -e TF_DSV41_COMP_BF16=${TF_DSV41_COMP_BF16:-} -e PYTORCH_CUDA_ALLOC_CONF=${PYTORCH_CUDA_ALLOC_CONF:-} -e TF_ROUTE_STATS=${TF_ROUTE_STATS:-} -e TF_ZB=${TF_ZB:-121,101} -e TF_ROUND_PROF=${TF_ROUND_PROF:-} -e TF_STEP_THREADS=${TF_STEP_THREADS:-16} -e TF_SKIP_READS=${TF_SKIP_READS:-} -e TF_SPLIT_READS=${TF_SPLIT_READS:-} -e TF_SKIP_SHARED=${TF_SKIP_SHARED:-} -e TF_FOLD_SHARED=${TF_FOLD_SHARED:-} -e TF_ROUTER_SLICES=${TF_ROUTER_SLICES:-} -e TF_L2_PREFETCH=${TF_L2_PREFETCH:-} -e TF_L2_SITES=${TF_L2_SITES:-} -e TF_L2_PACE_GBPS=${TF_L2_PACE_GBPS:-} -e TF_L2_PACE_CTAS=${TF_L2_PACE_CTAS:-} -e TF_L2_PACE_DELAY_US=${TF_L2_PACE_DELAY_US:-} -e TF_L2_PACE_SITES=${TF_L2_PACE_SITES:-} -e TF_L2_JOIN=${TF_L2_JOIN:-} -e TF_DSV41_DRAFT_RESET=${TF_DSV41_DRAFT_RESET:-} -e TF_DSV41_DRAFT_PRIOR=${TF_DSV41_DRAFT_PRIOR:-} -e TF_DSV41_DRAFT_RELAX=${TF_DSV41_DRAFT_RELAX:-} -e TF_DSV41_DRAFT_GRAMMAR=${TF_DSV41_DRAFT_GRAMMAR:-} -e TF_DSV41_COSTS=${TF_DSV41_COSTS:-} -e TF_DSV41_COST_CURVE=${TF_DSV41_COST_CURVE:-} -e TF_DSV41_CALIB_REPS=${TF_DSV41_CALIB_REPS:-} -e TF_DSV41_DRAFT_BORROW=${TF_DSV41_DRAFT_BORROW:-} -e TF_DSV41_L2_DISCARD_ROWS=${TF_DSV41_L2_DISCARD_ROWS:-} -e TF_MULTI_PROF=${TF_MULTI_PROF:-} -e TF_FUSE_HC_DECODE=${TF_FUSE_HC_DECODE:-} -e TF_SUBPROF=${TF_SUBPROF:-} -e TF_GROUPED_WO_A=${TF_GROUPED_WO_A:-} -e TF_MQA_CHUNK=${TF_MQA_CHUNK:-} -e TF_EXL3_ROT_FUSE=${TF_EXL3_ROT_FUSE:-} -e TF_PF_WOA=${TF_PF_WOA:-} -e TF_PF_PROGRAMS=${TF_PF_PROGRAMS:-} -e TF_COPY_DRAFTS=${TF_COPY_DRAFTS:-} -e TF_COPY_MAX=${TF_COPY_MAX:-} -e TF_COMM=${TF_COMM:-} -e TF_RDMA_MAX_KB=${TF_RDMA_MAX_KB:-} -e TF_RDMA_HOST=${TF_RDMA_HOST:-} -e TF_DSV41_MARKOV=${TF_DSV41_MARKOV:-} -e TF_DSV41_MARKOV_CACHE=${TF_DSV41_MARKOV_CACHE:-} -e TF_ONE_GRAPH=${TF_ONE_GRAPH:-} -e TF_DSV41_SHARED_POOL=${TF_DSV41_SHARED_POOL:-} -e TF_DSV41_POOL_TOKENS=${TF_DSV41_POOL_TOKENS:-} -e TF_DSV41_KEPT_ENTRIES=${TF_DSV41_KEPT_ENTRIES:-} -e TF_DSV41_KEEP_MIN=${TF_DSV41_KEEP_MIN:-} -e TF_DSV41_POOL_KEEP=${TF_DSV41_POOL_KEEP:-} -e TF_DSV41_GROW_AHEAD=${TF_DSV41_GROW_AHEAD:-} -e TF_CHUNK_PREFILL=${TF_CHUNK_PREFILL:-} -e TF_DSV41_FAST_TOPK=${TF_DSV41_FAST_TOPK:-} -e TF_DSV41_PREPARED=${TF_DSV41_PREPARED:-} -e TF_EXPERT_LOADS=${TF_EXPERT_LOADS:-} -e TF_EXPERT_LOADS_CFG=${TF_EXPERT_LOADS_CFG:-} -e TF_TAIL_TEST=${TF_TAIL_TEST:-} -e TF_DSV41_BOUNDED_TAIL=${TF_DSV41_BOUNDED_TAIL:-} -e NUMPY_MADVISE_HUGEPAGE=0 -e TF_DSV41_WIDTHS=${TF_DSV41_WIDTHS:-} -e TF_DSV41_SHARED_GRAPHS=${TF_DSV41_SHARED_GRAPHS:-} -e TF_NSYS=${TF_NSYS:-} -e TF_DECODE_PROF=${TF_DECODE_PROF:-} -e TF_DSV41_CUDA_MQA=${TF_DSV41_CUDA_MQA:-} -e TF_DSV41_SHARED_IK=${TF_DSV41_SHARED_IK:-} -e TF_DSV41_MQA_GROUP=${TF_DSV41_MQA_GROUP:-} -e TF_DSV41_MQA_FEW=${TF_DSV41_MQA_FEW:-} -e TF_DECODE_ROWS=${TF_DECODE_ROWS:-} -e TF_PROF_AT=${TF_PROF_AT:-} -e TF_STUDY_TIE=${TF_STUDY_TIE:-} -e TF_DSV41_SELECT_ONCE=${TF_DSV41_SELECT_ONCE:-} -e TF_DSV41_SEG_ROWS=${TF_DSV41_SEG_ROWS:-} -e TF_DSV41_FULL_DEQ=${TF_DSV41_FULL_DEQ:-} -e TF_DSV41_FULL_DEQ_MIB=${TF_DSV41_FULL_DEQ_MIB:-} -e TF_DSV41_IDX_BASE=${TF_DSV41_IDX_BASE:-} -e TF_DSV41_HC_SPLIT=${TF_DSV41_HC_SPLIT:-} -e TF_DSV41_HC_SIDE=${TF_DSV41_HC_SIDE:-} -e TF_DSV41_HC_SIDE_PART=${TF_DSV41_HC_SIDE_PART:-} -e TF_X3LD_ORDER=${TF_X3LD_ORDER:-} -e TF_EXPERT_GROUP=${TF_EXPERT_GROUP:-} -e TF_X3LD_PDL=${TF_X3LD_PDL:-} -e TF_DSV41_CAND_BOUND=${TF_DSV41_CAND_BOUND:-} -e TF_DSV41_ROUTE_WARPS=${TF_DSV41_ROUTE_WARPS:-} -e TF_ROUTER_BE=${TF_ROUTER_BE:-} -e TF_DSV41_TOPK_DIGITS=${TF_DSV41_TOPK_DIGITS:-} -e TF_DSV41_IDX_FORK=${TF_DSV41_IDX_FORK:-} -e TF_DSV41_PREFILL_PROF=${TF_DSV41_PREFILL_PROF:-} -e TF_DSV41_PREFILL_AHEAD=${TF_DSV41_PREFILL_AHEAD:-} -e TF_L2_ATTN_WQB_MB=${TF_L2_ATT